import { readFile, mkdir, writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

// This is the structural template formerly emitted alongside care's native event
// catalog. Own it here once: the engine consumes the generated type and every
// environment catalog imports that public type instead of emitting another copy.
export function renderEventFieldShape() {
  return [
    '// GENERATED by scripts/generate-event-field-shape.mjs — do not edit by hand.',
    '// Shared selector structure; native event names and payloads belong to the environment.',
    '',
    '/**',
    ' * A scalar leaf is null; any is opaque. Objects describe fields and an index',
    ' * shape, arrays describe elements, and unions accept any listed alternative.',
    ' */',
    "export type EventFieldShape = null | 'any'",
    "  | { kind: 'object'; fields: Record<string, EventFieldShape>; index: EventFieldShape | null }",
    "  | { kind: 'array'; element: EventFieldShape }",
    "  | { kind: 'union'; options: EventFieldShape[] }",
    '',
  ].join('\n')
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const output = new URL('../src/generated/event-field-shape.ts', import.meta.url)
  const text = renderEventFieldShape()
  if (process.argv.includes('--check')) {
    const current = await readFile(output, 'utf8')
    if (current !== text) throw new Error('generated-event-field-shape-stale; run pnpm generate:types')
    console.log('generated EventFieldShape matches its canonical template')
  } else {
    await mkdir(new URL('../src/generated/', import.meta.url), { recursive: true })
    await writeFile(output, text)
    console.log('generated the shared EventFieldShape contract')
  }
}
